const data = $input.first().json;

// =====================================================
// BUSCAR TELEGRAM CHAT ID EN TODO EL PAYLOAD
// =====================================================

function buscarChatId(valor, visitados = new Set()) {

  if (valor === null || valor === undefined) {
    return '';
  }

  // Si llega como string JSON, intentar parsearlo
  if (typeof valor === 'string') {

    const texto = valor.trim();

    // Buscar directamente dentro del string
    const match = texto.match(
      /"(?:telegram_chat_id|telegramChatId|chat_id)"\s*:\s*"?(.*?)"?(?:,|})/i
    );

    if (match?.[1]) {
      return String(match[1])
        .replace(/"$/, '')
        .trim();
    }

    if (
      (texto.startsWith('{') && texto.endsWith('}')) ||
      (texto.startsWith('[') && texto.endsWith(']'))
    ) {
      try {
        const parsed = JSON.parse(texto);
        return buscarChatId(parsed, visitados);
      } catch {
        return '';
      }
    }

    return '';
  }

  if (typeof valor !== 'object') {
    return '';
  }

  if (visitados.has(valor)) {
    return '';
  }

  visitados.add(valor);

  // Primero buscar las claves conocidas
  const clavesChat = [
    'telegram_chat_id',
    'telegramChatId',
    'chat_id'
  ];

  for (const clave of clavesChat) {
    if (
      valor[clave] !== undefined &&
      valor[clave] !== null &&
      String(valor[clave]).trim() !== ''
    ) {
      return String(valor[clave]).trim();
    }
  }

  // Después recorrer todo el objeto
  for (const clave of Object.keys(valor)) {

    const encontrado =
      buscarChatId(valor[clave], visitados);

    if (encontrado) {
      return encontrado;
    }
  }

  return '';
}


// =====================================================
// DATOS DEL ERROR
// =====================================================

const execution =
  data.execution ?? {};

const workflow =
  data.workflow ?? {};

const error =
  execution.error ??
  data.error ??
  {};


// =====================================================
// DATOS GENERALES
// =====================================================

const workflowName =
  workflow.name ??
  'InmoLead IA';

const nodoError =
  execution.lastNodeExecuted ??
  error.node?.name ??
  error.nodeName ??
  error.node ??
  'Nodo desconocido';

const mensajeError =
  error.message ??
  error.description ??
  execution.error?.message ??
  'Error no identificado en la ejecución del workflow.';

const tipoTecnico =
  error.name ??
  error.type ??
  'Error de ejecución';

const executionId =
  execution.id ??
  null;

const executionUrl =
  execution.url ??
  null;


// =====================================================
// CHAT ID
// =====================================================

const telegramChatId =
  buscarChatId(data);


// =====================================================
// CLASIFICACIÓN
// =====================================================

let tipo = 'Desconocido';

const texto =
  `${nodoError} ${mensajeError}`.toLowerCase();

if (texto.includes('notion')) {

  tipo = 'Notion';

} else if (texto.includes('telegram')) {

  tipo = 'Telegram';

} else if (texto.includes('slack')) {

  tipo = 'Slack';

} else if (
  texto.includes('gemini') ||
  texto.includes('google generative') ||
  texto.includes('language model')
) {

  tipo = 'Gemini';

} else if (
  texto.includes('parse') ||
  texto.includes('json')
) {

  tipo = 'Parsing';

} else if (
  texto.includes('validation') ||
  texto.includes('validación')
) {

  tipo = 'Validación';

} else if (
  texto.includes('api') ||
  texto.includes('http') ||
  texto.includes('request')
) {

  tipo = 'Integración';
}


// =====================================================
// SALIDA
// =====================================================

return [
  {
    json: {

      workflow:
        workflowName,

      nodo:
        String(nodoError),

      mensaje:
        String(mensajeError),

      tipo_tecnico:
        String(tipoTecnico),

      tipo,

      telegram_chat_id:
        telegramChatId,

      tiene_telegram_chat_id:
        Boolean(telegramChatId),

      execution_id:
        executionId
          ? String(executionId)
          : '',

      execution_url:
        executionUrl ?? '',

      fecha:
        new Date().toISOString(),

      reintentos:
        0,

      resuelto:
        false,

      observaciones:
        'Error capturado automáticamente por el Error Handler global.'
    }
  }
];
